import{_ as a,c as n,o as s,aj as i}from"./chunks/framework.CSCBGoZg.js";const h=JSON.parse('{"title":"Cron","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cron.md","filePath":"guide/cron.md","lastUpdated":0}'),o={name:"guide/cron.md"};function l(r,e,t,d,c,p){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="cron" tabindex="-1">Cron <a class="header-anchor" href="#cron" aria-label="Permalink to “Cron”">​</a></h1><p>Some features of Reeve make use of Cron expressions for scheduling periodically occuring events.</p><p>A Cron expression consists of 5 fields, each for a different interval of time:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*     *     *     *     *</span></span>
<span class="line"><span></span></span>
<span class="line"><span>^     ^     ^     ^     ^</span></span>
<span class="line"><span>|     |     |     |     |</span></span>
<span class="line"><span>|     |     |     |     +----- day of week (0-6) (Sunday=0)</span></span>
<span class="line"><span>|     |     |     +------- month (1-12)</span></span>
<span class="line"><span>|     |     +--------- day of month (1-31)</span></span>
<span class="line"><span>|     +----------- hour (0-23)</span></span>
<span class="line"><span>+------------- min (0-59)</span></span></code></pre></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><ul><li><code>* * * * *</code> run on every minute</li><li><code>10 * * * *</code> run at 0:10, 1:10 etc</li><li><code>10 15 * * *</code> run at 15:10 every day</li><li><code>* * 1 * *</code> run on every minute on 1st day of month</li><li><code>0 0 1 1 *</code> Happy new year schedule</li><li><code>0 0 * * 1</code> Run at midnight on every Monday</li></ul><h2 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to “Lists”">​</a></h2><ul><li><code>* 10,15,19 * * *</code> run at 10:00, 15:00 and 19:00</li><li><code>1-15 * * * *</code> run at 1, 2, 3...15 minute of each hour</li><li><code>0 0-5,10 * * *</code> run on every hour from 0-5 and in 10 oclock</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ul><li><code>*/2 * * * *</code> run every two minutes</li><li><code>10 */3 * * *</code> run every 3 hours on 10th min</li><li><code>0 12 */2 * *</code> run at noon on every two days</li><li><code>1-59/2 * * * *</code> run every two minutes, but on odd minutes</li></ul>`,10)])])}const m=a(o,[["render",l]]);export{h as __pageData,m as default};
